sqlite3 -header -column /workspace/.worlds/yard-trace/world/world.sqlite "
SELECT h.move_id, h.work_order, h.from_point, h.material_note, h.quantity_kg, h.logged_at
FROM hopper_move h
WHERE h.work_order = 'OUT-5002' AND h.from_point = 'BIN-12' AND h.quantity_kg = '26000';

SELECT ht.scale_ticket, ht.move_id, ht.work_order, ht.from_point, ht.quantity_kg
FROM hopper_ticket_named ht
WHERE ht.work_order = 'OUT-5002' AND ht.from_point = 'BIN-12' AND ht.quantity_kg = '26000';

SELECT i.scale_ticket, i.receipt_no, i.grower_recorded, i.assigned_bin, i.net_kg
FROM hopper_ticket_named ht
JOIN intake i ON i.ticket_id = 'ticket:' || ht.scale_ticket
WHERE ht.work_order = 'OUT-5002' AND ht.from_point = 'BIN-12';

SELECT dispatch_ref, bin_label, quantity_kg FROM loadout WHERE dispatch_ref = 'PGE-OUT-5002';
"

